package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
)

const mod = 1000000007

func isPrime(k int) bool {
	if k <= 1 {
		return false
	}
	if k <= 3 {
		return true
	}
	if k%2 == 0 {
		return false
	}
	limit := int(math.Sqrt(float64(k)))
	for i := 3; i <= limit; i += 2 {
		if k%i == 0 {
			return false
		}
	}
	return true
}

func power(x, p int64) int64 {
	res := int64(1)
	x %= mod
	for p > 0 {
		if p&1 == 1 {
			res = (res * x) % mod
		}
		x = (x * x) % mod
		p >>= 1
	}
	return res
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	x, _ := strconv.Atoi(scanner.Text())

	scanner.Scan()
	n, _ := strconv.ParseInt(scanner.Text(), 10, 64)

	primes := make(map[int]bool)

	limit := int(math.Sqrt(float64(x)))
	for i := 2; i <= limit; i++ {
		if x%i == 0 {
			if isPrime(i) {
				primes[i] = true
			}
			j := x / i
			if isPrime(j) {
				primes[j] = true
			}
		}
	}
	if isPrime(x) {
		primes[x] = true
	}

	ans := int64(1)

	for p := range primes {
		p64 := int64(p)
		curP := p64
		for n/curP > 0 {
			ans = (ans * power(p64, n/curP)) % mod
			nextCurP := curP * p64
			if nextCurP/p64 != curP {
				break
			}
			curP = nextCurP
		}
	}

	fmt.Println(ans)
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

const mod = 1000000007

type Scanner struct {
	scanner *bufio.Scanner
}

func NewScanner() *Scanner {
	s := bufio.NewScanner(os.Stdin)
	s.Split(bufio.ScanWords)
	return &Scanner{s}
}

func (s *Scanner) NextInt() int {
	s.scanner.Scan()
	val := 0
	for _, c := range s.scanner.Bytes() {
		val = val*10 + int(c-'0')
	}
	return val
}

func (s *Scanner) NextLong() int64 {
	s.scanner.Scan()
	val := int64(0)
	for _, c := range s.scanner.Bytes() {
		val = val*10 + int64(c-'0')
	}
	return val
}

func power(x, p int64) int64 {
	res := int64(1)
	x %= mod
	for p > 0 {
		if p&1 == 1 {
			res = (res * x) % mod
		}
		x = (x * x) % mod
		p >>= 1
	}
	return res
}

func main() {
	sc := NewScanner()
	x := sc.NextInt()
	n := sc.NextLong()

	primes := []int{}
	tempX := x
	for i := 2; i*i <= tempX; i++ {
		if tempX%i == 0 {
			primes = append(primes, i)
			for tempX%i == 0 {
				tempX /= i
			}
		}
	}
	if tempX > 1 {
		primes = append(primes, tempX)
	}

	ans := int64(1)
	for _, p := range primes {
		p64 := int64(p)
		curP := p64
		for curP <= n {
			ans = (ans * power(p64, n/curP)) % mod
			if curP > n/p64 {
				break
			}
			curP *= p64
		}
	}

	fmt.Println(ans)
}

