package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

const MOD int64 = 1000000007

type Scanner struct {
	reader *bufio.Reader
	tokens []string
}

func NewScanner(r *bufio.Reader) *Scanner {
	return &Scanner{reader: r}
}

func (s *Scanner) Next() string {
	for len(s.tokens) == 0 {
		line, err := s.reader.ReadString('\n')
		if err != nil {
			return ""
		}
		s.tokens = strings.Fields(line)
	}
	token := s.tokens[0]
	s.tokens = s.tokens[1:]
	return token
}

func (s *Scanner) NextInt() int {
	val, _ := strconv.Atoi(s.Next())
	return val
